    KanbanGridWidget.prototype._getMetaChildrens = function (id) {
        let node = this._client.getNode(id);
        let metaNodes = this._client.getAllMetaNodes();
        let attributes;
        if(node && metaNodes){
            let validChilds = node.getValidChildrenMetaIds(metaNodes);
            let metaChild;
            
            validChilds.forEach(path=>{
                let auxMetaChild = this._client.getNode(path);
                if(auxMetaChild.getAttribute('name')===CLASS_NAME ){
                    metaChild = auxMetaChild;
                }
            });
            attributes =  metaChild ? metaChild.getAttributeMeta(FIELD_FILTER) : null;
            }   
        return attributes ? attributes.enum: null;
    };
    KanbanGridWidget.prototype._getRegionNodes = function(id, trelloRegions){
        let self = this;
        let nodes = {};
        let node = this._client.getNode(id);
        if(!trelloRegions) {
            return {};
        }
        trelloRegions.forEach(path=>{
            nodes[path] = []; 
        });
        let childrens = node.getChildrenIds();
        childrens.forEach(childId=>{
            let info = self._getNodeInfo(childId);
            let keys = Object.keys(nodes);
            /*if (info && keys.includes(info.metaId)) {
                nodes[info.metaId].push(info);
            }*/
            if (info && keys.includes(info.type)) {
                nodes[info.type].push(info);
            }
        });
        trelloRegions.forEach(path=>{
            nodes[path] = nodes[path].sort(self.compareByOrder); 
        });
        return nodes;
    }
    KanbanGridWidget.prototype.compareByOrder = function (a, b) {
        return a.order - b.order;
    }
    KanbanGridWidget.prototype._getNodeInfo = function (id) {
        var node = this._client.getNode(id),
            objDescriptor;
        if (node) {
            var metaObj = this._client.getNode(node.getMetaTypeId()),
            metaName = undefined;
            if (metaObj) {
                metaName = metaObj.getAttribute(nodePropertyNames.Attributes.name);
            }

            objDescriptor = {
                id: node.getId(),
                title: node.getAttribute(nodePropertyNames.Attributes.name),
                order: node.getAttribute(FIELD_ORDER) ? node.getAttribute(FIELD_ORDER) : 0,
                childrenIds: node.getChildrenIds(),
                parentId: node.getParentId(),
                isConnection: GMEConcepts.isConnection(id),
                meta: metaName,
                metaId: node.getMetaTypeId(),
                type: node.getAttribute(FIELD_FILTER) ? node.getAttribute(FIELD_FILTER) : '',
            };
        }
        return objDescriptor;
    }
    KanbanGridWidget.prototype._paintTrelloRegions = function(trelloRegions){
        let self = this;
        let trelloPanel = self._el.find('#boardlists')[0];
        if (!trelloRegions){
            return;
        }
        trelloRegions.forEach(path=>{
            let trelloRegionId = path.replace(/ /g,"_");
            let nodeChildName = path;
            let divColumn = document.createElement("div");
            divColumn.className = "board-list";
            divColumn.setAttribute("id", "list"+trelloRegionId);
            divColumn.ondragover=  function (ev){
                ev.preventDefault();
            };
            divColumn.ondrop = function(ev){   
                ev.preventDefault();
                let sourceId = ev.dataTransfer.getData("text/plain");
                let sourceIdEl=document.getElementById(sourceId);
                if (!sourceIdEl) return
                let sourceIdParentEl=sourceIdEl.parentElement;
                let targetEl=document.getElementById(ev.target.id);
                if (!targetEl) return
                let targetParentEl=targetEl.parentElement;
                let id = sourceId.split('card')[1];
                
                self._client.startTransaction();
                if (targetParentEl.id!==sourceIdParentEl.id){
                    
                    if (targetEl.className === sourceIdEl.className ){
                        targetParentEl.appendChild(sourceIdEl);
                        let type = targetParentEl.id.split('list')[1];
                        type = type.replace(/_/g," ");
                        self._client.setAttributes(id, FIELD_FILTER,type);
                        self.setOrder(targetParentEl);
                    }else{
                        let id = sourceId.split('card')[1];
                         targetEl.appendChild(sourceIdEl); 
                         let type = ev.target.id.split('list')[1];
                         type = type.replace(/_/g," ");
                         self._client.setAttributes(id, FIELD_FILTER,type);
                         self.setOrder(targetEl);
                    }
                }else{
                    let holder=targetEl;
                    let holderText=holder.textContent;
                    let hoderId = holder.id;
                    targetEl.textContent=sourceIdEl.textContent;
                    targetEl.id=sourceIdEl.id;
                    sourceIdEl.textContent=holderText;
                    sourceIdEl.id=hoderId;
                    hoderId = ''
                    holderText='';
                    self.setOrder(targetEl.parentElement);
                }
                self._client.completeTransaction(); 
            }
            let divColumnTitle = document.createElement("div");
            divColumnTitle.className = "list-title";
            divColumnTitle.innerText = nodeChildName;
            divColumn.appendChild(divColumnTitle)
            trelloPanel.appendChild(divColumn);
        });
    }
    
    KanbanGridWidget.prototype.setOrder = function (element) {
        let self = this;
        let elements = [];
        element.childNodes.forEach(element=>{
            if(element.id.indexOf('card')!== -1){
                elements.push(element.id.split('card')[1]);
            }
        });
        elements.forEach((id,index)=>{
            self._client.setAttributes(id, FIELD_ORDER,parseInt(index+1));
        });
    }
