    KanbanGridWidget.prototype._paintTrelloNodes = function(trelloNodes){
        let self = this;
        let keys = Object.keys(trelloNodes);
        keys.forEach(path=>{
            let trelloRegionId = path.replace(/ /g,'_');
            let divList = self._el.find("#list"+trelloRegionId)[0];
            trelloNodes[path].forEach(node=>{
                let divCard = self.createNodeTask(node.id);
                divList.appendChild(divCard);
            });
        });
    }
    KanbanGridWidget.prototype.createNodeTask = function (id) {
        let self = this;
        let divCard = document.createElement("div");
        let nodeChild =  self._client.getNode(id);
        let nodeChildName = nodeChild ? nodeChild.getAttribute('name') : null;
        divCard.className = "card";
        divCard.setAttribute("id", "card"+id);
        divCard.draggable = true;
        divCard.ondragstart = function(ev){
            ev.dataTransfer.setData("text/plain", ev.target.id);
        };
        divCard.ondblclick = function(ev){
            let id = divCard.id.split('card')[1];
            WebGMEGlobal.State.registerActiveSelection([id]);
        }
        let iconDelete = document.createElement("i");
        let divText = document.createElement("div");
        divText.className = "col-xs-9";
        divText.innerText = nodeChildName;
        iconDelete.className = "col-xs-3 fa fa-trash";
        iconDelete.setAttribute("aria-hidden", "true");
        iconDelete.setAttribute("style", "text-align: right;");
        iconDelete.onclick = function(ev){
            let id = divCard.id.split('card')[1];
            self._client.deleteNode([id]);
            self.removeNode(id)
        }
        divCard.appendChild(divText);
        divCard.appendChild(iconDelete);

        return divCard;
    }
    KanbanGridWidget.prototype._makeDroppable = function (trelloRegions) {
        var self = this,
            desc;
        self._el.addClass('drop-area');
        let type = trelloRegions[0];
        let trelloRegionId = type.replace(/ /g,'_');
        let divList = self._el.find("#list"+trelloRegionId)[0];
        dropTarget.makeDroppable(self._el, {
            over: function (event, dragInfo) {
                if (self._isValidDrop(dragInfo)) {
                    self._el.addClass('accept-drop');
                } else {
                    self._el.addClass('reject-drop');
                }
            },
            out: function (/*event, dragInfo*/) {
                self._el.removeClass('accept-drop reject-drop');
            },
            drop: function (event, dragInfo) {
                console.log(dragInfo);
                console.log(event);
                if (self._isValidDrop(dragInfo)) {
                    let id = self.createNode(null, dragInfo[DROP_CONSTANTS.DRAG_ITEMS][0]);

                    let divCard = self.createNodeTask(id);
                    divList.appendChild(divCard);
                }
                self._el.removeClass('accept-drop reject-drop');
            }
        });
    };
    KanbanGridWidget.prototype.createNode = function(nodePath, metaNodeId) {
        var self = this;
        this.createControl = true;
        var client = self._client;
        var parentId = WebGMEGlobal.State.getActiveObject(), // for our seeds, /v is always 'Projects'
            node = client.getNode(nodePath),
            baseId = metaNodeId ? metaNodeId : node.getBaseId(),
            baseNode = client.getNode(baseId),
            baseName = baseNode.getAttribute('name');
            var childCreationParams = {
                parentId: parentId,  // Should be Projects (/v)
                baseId: baseId,    // should be META:Project
            };
            return client.createChild(childCreationParams, 'Creating new '+baseName);
             
    };
    KanbanGridWidget.prototype._isValidDrop = function (dragInfo) {
        var self = this;
        if (!dragInfo)
            return false;
        var self = this;
        var result = false,
            draggedNodePath,
            nodeObj,
            nodeName,
            metaObj,
            metaName;
        if (dragInfo[DROP_CONSTANTS.DRAG_ITEMS].length === 1) {
            draggedNodePath = dragInfo[DROP_CONSTANTS.DRAG_ITEMS][0];
            nodeObj = self._client.getNode(draggedNodePath);
            nodeName = nodeObj.getAttribute('name');
            metaObj = self._client.getNode(nodeObj.getMetaTypeId());
            if (metaObj) {
                metaName = metaObj.getAttribute('name');
            }
            result = metaName && metaName != 'Note';
        }
        return result;
    }
