    KanbanGridWidget.prototype.removeNode = function (gmeId) {
        let nodeId = WebGMEGlobal.State.getActiveObject();
        if(nodeId === gmeId){
            if((gmeId.split("/").length-1)>1){
                let rootPath = gmeId.split('/');
                let rootParent ="";
                for(let i=1; i<rootPath.length-1; i++){
                    rootParent += '/'+rootPath[i]; 
                }
                    WebGMEGlobal.State.registerActiveObject(rootParent);
            }else{
                WebGMEGlobal.State.registerActiveObject(CONSTANTS.PROJECT_ROOT_ID);
            }
        }else{
            this.refreshWidget();
        }
    };
